<?php
require_once('../path.php');
$manifest_file = ROOT_PATH . '/assets/data/api_endpoints.json';
$endpoints = json_decode((string) @file_get_contents($manifest_file), true) ?: [];
$groups = [];
foreach ($endpoints as $endpoint) {$groups[$endpoint['group']][] = $endpoint;}
$order=['Authentication','Transactions','Dashboard','Categories','Reports','Shopping','Home management','Notifications','User','Information','API v1','Shortcuts API','Web app internals','Admin internals','AI chat internals','Admin AI internals'];
uksort($groups,function($a,$b)use($order){$ia=array_search($a,$order,true);$ib=array_search($b,$order,true);return($ia===false?999:$ia)<=>($ib===false?999:$ib);});
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function slug($v){return trim(preg_replace('/[^a-z0-9]+/i','-',strtolower($v)),'-');}
function request_example($e){$method=$e['methods'][0]??'GET';$path=$e['path'];$params=$e['params']??[];$auth=$e['auth']??'';$headers=[];$body=[];foreach($params as $p){$body[$p]=preg_match('/(^|_)(id|limit|offset|month|year|m|y)$/',$p)?1:'value';}if(strpos($auth,'API token')!==false)$body=['token'=>'YOUR_API_TOKEN']+$body;if(strpos($auth,'Shortcut')!==false)$body=['api_token'=>'YOUR_SHORTCUT_TOKEN']+$body;if($method==='GET'&&$body){$path.='?'.http_build_query($body);} $lines=['curl -X '.$method.' "https://hatazrim.com'.$path.'"'];if($method!=='GET'&&$body){$headers[]='  -H "Content-Type: application/json"';$headers[]="  -d '".json_encode($body,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)."'";}return implode(" \\\n",array_merge($lines,$headers));}
?><!doctype html><html lang="he" dir="rtl"><head><?php include(ROOT_PATH.'/assets/includes/setup_meta_data.php');?><title>תיעוד API | התזרים</title><meta name="description" content="תיעוד ממשקי ה-API של התזרים: אימות, פעולות, קטגוריות, קניות וניהול הבית."><style>
