verflow:auto}.search{position:relative;margin-bottom:15px}.search input{width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:12px;padding:11px 34px 11px 11px;font:inherit}.search i{position:absolute;right:12px;top:13px;color:#99a3b2}.nav-title{font-size:.72rem;color:#9aa4b2;font-weight:800;margin:16px 8px 8px}.nav-link{display:flex;justify-content:space-between;gap:8px;text-decoration:none;color:#556175;border-radius:10px;padding:8px 9px;font-size:.87rem}.nav-link:hover{background:#f0faf5;color:var(--green2)}.nav-link b{font-size:.72rem;background:#eef1f5;padding:2px 7px;border-radius:999px}.content{min-width:0}.notice{background:#fff;border:1px solid var(--line);border-radius:20px;padding:22px;margin-bottom:22px;box-shadow:0 12px 35px rgba(38,51,73,.05)}.notice h2{font-size:1.1rem;margin:0 0 9px}.notice p{color:var(--muted);line-height:1.65;margin:0}.auth-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:16px}.auth-box{background:#f7f9fc;border:1px solid var(--line);border-radius:13px;padding:13px}.auth-box b{display:block;margin-bottom:5px}.auth-box code{font-size:.8rem;direction:ltr;display:block;overflow:auto;color:#46546a}.group{scroll-margin-top:18px;margin:0 0 35px}.group-head{display:flex;align-items:end;justify-content:space-between;margin:0 2px 13px}.group-head h2{font-size:1.55rem;margin:0}.group-head span{color:var(--muted);font-size:.82rem}.endpoint{background:#fff;border:1px solid var(--line);border-radius:18px;margin-bottom:12px;overflow:hidden;box-shadow:0 8px 24px rgba(38,51,73,.04)}.endpoint summary{list-style:none;cursor:pointer;padding:17px 18px;display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:center}.endpoint summary::-webkit-details-marker{display:none}.method{direction:ltr;font:800 .72rem monospace;color:#fff;background:var(--blue);border-radius:7px;padding:6px 8px;min-width:43px;text-align:center}.method.POST{background:var(--green)}.method.DELETE{background:var(--red)}.method.PUT,.method.PATCH{background:var(--orange)}.ep-path{direction:ltr;text-align:left;font:700 .89rem ui-monospace,monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chev{color:#9aa3af;transition:.2s}.endpoint[open] .chev{transform:rotate(180deg)}.ep-body{border-top:1px solid var(--line);padding:19px}.badges{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:17px}.badge{border-radius:999px;padding:6px 10px;font-size:.76rem;font-weight:800;background:#eef3fb;color:#46607b}.badge.support{background:#e8f8ef;color:#18844d}.badge.internal{background:#fff3dd;color:#a56405}.doc-grid{display:grid;min-width:0;grid-template-columns:1fr 1fr;gap:18px}.doc-grid>div{min-width:0;max-width:100%}.doc-grid h3{font-size:.85rem;margin:0 0 8px}.params{display:flex;flex-wrap:wrap;gap:6px}.param{direction:ltr;background:#f0f3f7;border:1px solid #e4e8ee;border-radius:7px;padding:4px 7px;font:12px monospace}.empty{color:#9aa3af;font-size:.82rem}.code{direction:ltr!important;text-align:left!important;unicode-bidi:isolate;display:block;width:100%;box-sizing:border-box;background:#142033;color:#e7edf6;border-radius:12px;padding:14px;margin:8px 0 0;overflow-x:auto;overflow-y:hidden;font:12px/1.6 ui-monospace,monospace;white-space:pre;max-height:230px}.response{direction:ltr!important;text-align:left!important;unicode-bidi:isolate;display:block;width:100%;box-sizing:border-box;background:#f7f9fc;border:1px solid var(--line);border-radius:10px;padding:11px;font:12px/1.55 ui-monospace,monospace;overflow-x:auto;overflow-y:auto}.code code{color:#e7edf6!important;min-width:max-content;white-space:pre}.response code{color:#263349!important;min-width:0;white-space:pre-wrap}.code code,.response code{direction:ltr!important;text-align:left!important;unicode-bidi:plaintext;font:inherit;display:block}.no-results{display:none;text-align:center;background:#fff;border-radius:18px;padding:40px;color:var(--muted)}.footer{text-align:center;color:#8c96a6;font-size:.82rem;padding:0 15px 40px}.scope-tabs{display:flex;gap:7px;overflow:auto;margin-bottom:16px}.scope-btn{white-space:nowrap;border:1px solid var(--line);background:#fff;color:#5d6878;border-radius:999px;padding:8px 12px;font:inherit;font-size:.78rem;cursor:pointer}.scope-btn.active{background:var(--ink);color:#fff;border-color:var(--ink)}@media(max-width:850px){.layout{grid-template-columns:1fr;margin-top:-25px}.sidebar{position:static;max-height:none}.sidebar .nav-title,.sidebar .nav-link{display:none}.scope-tabs{margin-bottom:0}.doc-grid{grid-template-columns:1fr}}@media(max-width:580px){.back-landing{font-size:0;width:36px;height:36px;padding:0;justify-content:center}.back-landing i{font-size:.85rem}.api-top{padding:22px 15px 44px}.hero{margin-top:42px}.brand img{width:120px}.layout{padding-inline:11px}.endpoint summary{grid-template-columns:auto minmax(0,1fr) auto;padding:14px 12px;gap:8px}.ep-body{padding:15px}.hero-meta{gap:6px}.auth-grid{grid-template-columns:1fr}.notice{padding:17px}}
</style></head><body><main class="api-page"><header class="api-top"><div class="api-top__in"><div class="brand"><a href="<?php echo BASE_URL;?>"><img src="<?php echo BASE_URL;?>assets/images/tazrim-logo-ver.png" alt="התזרים"></a><div class="brand-actions"><a class="back-landing" href="<?php echo BASE_URL;?>landing/index.php"><i class="fa-solid fa-arrow-right"></i> לאתר התזרים</a><span class="status">API פעיל</span></div></div><div class="hero"><h1>API למפתחים</h1><p>כל מה שצריך כדי לחבר אפליקציה, קיצור דרך או שירות לתזרים. הממשקים מסודרים לפי תחום, עם דרכי אימות, פרמטרים ודוגמאות שימוש.</p><div class="hero-meta"><span class="pill">JSON</span><span class="pill">HTTPS בלבד</span><span class="pill">UTF-8</span><span class="pill"><?php echo count($endpoints);?> נתיבים מתועדים</span></div></div></div></header><div class="layout"><aside class="sidebar"><div class="search"><i class="fa-solid fa-magnifying-glass"></i><input id="api-search" type="search" placeholder="חיפוש נתיב או פרמטר" aria-label="חיפוש בתיעוד"></div><div class="scope-tabs"><button class="scope-btn active" data-scope="all">כל הנתיבים</button></div><div class="nav-title">תחומים</div><?php foreach($groups as $name=>$items):?><a class="nav-link" href="#<?php echo h(slug($name));?>"><span><?php echo h($name);?></span><b><?php echo count($items);?></b></a><?php endforeach;?></aside><section class="content"><div class="notice"><h2>לפני שמתחילים</h2><p>הנתיבים בדף הזה מיועדים לאינטגרציות חיצוניות ומאומתים באמצעות טוקן. ממשקי האתר, נתיבי ניהול ונתיבים פנימיים אינם חשופים בתיעוד הציבורי.</p><div class="auth-grid"><div class="auth-box"><b>API v1</b><code>token=YOUR_API_TOKEN</code></div><div class="auth-box"><b>Shortcuts API</b><code>api_token=YOUR_SHORTCUT_TOKEN</code></div></div></div><?php foreach($groups as $name=>$items):?><section class="group" id="<?php echo h(slug($name));?>"><div class="group-head"><h2><?php echo h($name);?></h2><span><?php echo count($items);?> endpoints</span></div><?php foreach($items as $e):$scope=($e['stability']==='Supported'?'supported':'internal');?><details class="endpoint" data-scope="<?php echo $scope;?>" data-search="<?php echo h(strtolower($e['path'].' '.implode(' ',$e['params']).' '.$name));?>"><summary><span class="method <?php echo h($e['methods'][0]??'GET');?>"><?php echo h(implode('|',$e['methods']));?></span><code class="ep-path"><?php echo h($e['path']);?></code><i class="fa-solid fa-chevron-down chev"></i></summary><div class="ep-body"><div class="badges"><span class="badge <?php echo $scope==='supported'?'support':'internal';?>"><?php echo $scope==='supported'?'API נתמך':'ממשק פנימי';?></span><span class="badge"><?php echo h($e['auth']);?></span></div><div class="doc-grid"><div><h3>פרמטרים</h3><div class="params"><?php if($e['params']):foreach($e['params'] as $p):?><code class="param"><?php echo h($p);?></code><?php endforeach;else:?><span class="empty">אין פרמטרים מתועדים</span><?php endif;?></div><h3 style="margin-top:18px">דוגמת בקשה</h3><pre class="code" dir="ltr" tabindex="0" aria-label="דוגמת בקשת curl"><code dir="ltr"><?php echo h(request_example($e));?></code></pre></div><div><h3>מבנה תשובה</h3><pre class="response" dir="ltr" tabindex="0" aria-label="דוגמת תגובת JSON"><code dir="ltr"><?php echo h(json_encode($e['sample'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));?></code></pre><h3 style="margin-top:18px">פורמט</h3><div class="params"><code class="param">application/json</code><code class="param">UTF-8</code></div></div></div></div></details><?php endforeach;?></section><?php endforeach;?><div class="no-results" id="no-results">לא נמצאו נתיבים שמתאימים לחיפוש.</div></section></div><footer class="footer">התזרים API · התיעוד נוצר ישירות ממפת הנתיבים של המערכת</footer></main><script>(function(){var search=document.getElementById('api-search'),buttons=document.querySelectorAll('.scope-btn'),scope='all';function filter(){var q=(search.value||'').toLowerCase().trim(),shown=0;document.querySelectorAll('.endpoint').forEach(function(el){var okScope=scope==='all'||el.dataset.scope===scope,okText=!q||el.dataset.search.indexOf(q)>-1,show=okScope&&okText;el.style.display=show?'':'none';if(show)shown++;});document.querySelectorAll('.group').forEach(function(g){g.style.display=g.querySelector('.endpoint:not([style*="display: none"])')?'':'none';});document.getElementById('no-results').style.display=shown?'none':'block';}search.addEventListener('input',filter);buttons.forEach(function(b){b.addEventListener('click',function(){buttons.forEach(function(x){x.classList.remove('active')});b.classList.add('active');scope=b.dataset.scope;filter();});});})();</script></body></html>
